const $ = id => document.getElementById(id);
const esc = value => String(value ?? '').replace(/[&<>'"]/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]));
const slugStatus = value => String(value || '').toLowerCase().replace(/\s+/g,'-');
const isAdmin = () => state.profile?.role === 'admin';
const companyTools = () => state.tools.filter(t=>!t.privateTool && t.inventoryScope!=='personal');
const personalTools = () => isAdmin()?state.tools.filter(t=>t.privateTool || t.inventoryScope==='personal'):[];
const visibleTools = () => companyTools();
const formatPersonName = value => String(value||'Employee').trim().replace(/\b([a-z])/g, m=>m.toUpperCase());
const displayName = (user=state.user) => formatPersonName(state.profile?.displayName || user?.displayName || user?.email?.split('@')[0] || 'Employee');

function toast(message,error=false){const el=$('toast');el.textContent=message;el.classList.remove('hidden');el.style.background=error?'#991b1b':'#111827';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.add('hidden'),3300)}
function formatDate(ts){if(!ts)return'Just now';const d=ts.toDate?ts.toDate():new Date(ts);return d.toLocaleString([],{dateStyle:'medium',timeStyle:'short'})}
function formatDateOnly(value){if(!value)return'—';const d=new Date(`${value}T12:00:00`);return Number.isNaN(d.valueOf())?value:d.toLocaleDateString([],{dateStyle:'medium'})}
function openModal(id,push=true){$(id)?.classList.remove('hidden');if(push&&!state.suppressHistory)history.pushState({view:state.currentView,modal:id},'',location.href)}
function closeModal(id){$(id)?.classList.add('hidden')}
function icon(name){return ICONS[name]||ICONS.other}
function paintIcons(){document.querySelectorAll('[data-icon]').forEach(el=>{const inBottomNav=!!el.closest('.bottom-nav');el.innerHTML=inBottomNav?(NAV_ICONS[el.dataset.icon]||icon(el.dataset.icon)):icon(el.dataset.icon)})}
function currentLocation(id){return state.locations.find(l=>l.id===id)}
function currentCategory(id){return state.categories.find(c=>c.id===id)}
function currentJob(id){return state.jobs.find(j=>j.id===id)}
function normalizeBrand(v){return String(v||'').trim().toLowerCase()}
function brandPrefix(brand){const target=normalizeBrand(brand);for(const [name,prefix] of Object.entries(state.settings.brandPrefixes||{})){if(normalizeBrand(name)===target)return String(prefix).toUpperCase()}return ''}
function nextToolLabel(brand='',scope='company',excludeId=''){const configured=brandPrefix(brand);if(!configured)return '';const raw=configured.replace(/[^A-Z0-9]/g,'');const prefix=scope==='personal'?`P-${raw}`:raw;let max=0;const rows=(scope==='personal'?personalTools():companyTools()).filter(t=>t.id!==excludeId);const start=`${prefix}-`;for(const t of rows){for(const rawLabel of [t.label,...(Array.isArray(t.previousLabels)?t.previousLabels:[])]){const label=String(rawLabel||'').trim().toUpperCase();if((t.numberingCorrectionLabels||[]).some(x=>String(x).toUpperCase()===label))continue;if(label!=='P-B-43'||String(t.label||'').toUpperCase()!=='P-B-03'||String(t.model||'').toUpperCase()!=='GKS18V-25C'){if(label.startsWith(start)){const n=Number(label.slice(start.length));if(Number.isFinite(n))max=Math.max(max,n)}}}}return`${prefix}-${String(max+1).padStart(2,'0')}`}
function activeLocations(){return state.locations.filter(x=>x.active!==false).sort((a,b)=>(a.name||'').localeCompare(b.name||''))}
function activeCategories(){return state.categories.filter(x=>x.active!==false).sort((a,b)=>(a.order??999)-(b.order??999)||(a.name||'').localeCompare(b.name||''))}
function mapsURL(address){return`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(address||'')}`}
function warrantyState(date){if(!date)return null;const today=new Date();today.setHours(0,0,0,0);const expiry=new Date(`${date}T12:00:00`);const days=Math.ceil((expiry-today)/86400000);return{days,label:days<0?'Expired':days<=60?`${days} days left`:'Active'}}
function dateValue(v){if(!v)return null;if(v.toDate)return v.toDate();const d=new Date(String(v).length===10?`${v}T12:00:00`:v);return Number.isNaN(d.valueOf())?null:d}
function daysSince(v){const d=dateValue(v);if(!d)return Infinity;return Math.floor((Date.now()-d.getTime())/86400000)}
function verificationState(t){const months=Number(t.photoReminderMonths ?? 6),cycle=Math.max(1,months||6)*30,never=!t.lastVerified,age=daysSince(t.lastVerified),dueSoon=!never&&months>0&&age>=Math.max(0,cycle-14)&&age<cycle,dueNow=!never&&months>0&&age>=cycle&&age<=cycle+14,overdue=!never&&months>0&&age>cycle+14,photoDue=!never&&months>0&&daysSince(t.conditionPhotoAt||t.lastVerified)>=cycle,deferred=t.attentionDeferredUntil&&new Date(t.attentionDeferredUntil+'T23:59:59')>new Date(),manual=!!t.needsAttention&&!deferred,missing=['Missing','Lost'].includes(t.status);return{stale:never||dueNow||overdue,dueSoon,dueNow,overdue,photoDue,deferred,never,needs:never||dueSoon||dueNow||overdue||photoDue||manual||missing||t.status==='Repair',label:missing?'Missing':manual?(t.attentionReason||'Needs attention'):never?'Needs verification':overdue?'Verification overdue':dueNow?'Verification due now':dueSoon?'Verification due soon':photoDue?'Condition photo due':t.status==='Repair'?'Needs repair':deferred?'Attention deferred':'Verified'}}
function duplicateMatches(id=''){const brand=normalizeBrand($('toolBrand')?.value),model=String($('toolModel')?.value||'').trim().toLowerCase(),name=String($('toolName')?.value||'').trim().toLowerCase(),serial=String($('toolSerial')?.value||'').trim().toLowerCase();return state.tools.filter(t=>t.id!==id&&t.status!=='Retired'&&((serial&&String(t.serial||'').trim().toLowerCase()===serial)||(model&&String(t.model||'').trim().toLowerCase()===model&&normalizeBrand(t.brand)===brand)||(name&&name.length>3&&String(t.name||'').trim().toLowerCase()===name&&normalizeBrand(t.brand)===brand)))}
function showDuplicateWarning(){const el=$('duplicateWarning');if(!el)return;const matches=duplicateMatches($('toolId')?.value||'');if(!matches.length){el.classList.add('hidden');el.innerHTML='';return}const serial=String($('toolSerial')?.value||'').trim().toLowerCase(),exact=matches.filter(t=>serial&&String(t.serial||'').trim().toLowerCase()===serial),labels=matches.map(t=>`${t.label||'—'}${(t.privateTool||t.inventoryScope==='personal')?' (Personal)':' (Company)'}`).join(', ');el.classList.remove('hidden');el.innerHTML=`<strong>${exact.length?'Exact serial already exists':'Matching physical assets'}: ${esc(labels)}</strong><span>${exact.length?'Check this serial before saving.':'Same make and model is allowed when this is another physical unit.'}</span><small>Retired assets are excluded. Company and Personal are checked together.</small><button type="button" class="btn smallbtn" data-view-matching-assets>View existing</button>`}


function applyTheme(theme){let resolved=theme;if(theme==='system')resolved=matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';document.documentElement.dataset.theme=resolved;localStorage.setItem('tt-theme',theme);$('themeBtn').textContent=resolved==='dark'?'☀':'☾'}
function updateGreeting(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Vancouver',hour:'numeric',hour12:false}).formatToParts(new Date());const hour=Number(parts.find(p=>p.type==='hour')?.value||12);const greeting=hour>=3&&hour<=11?'Good morning':hour>=12&&hour<=17?'Good afternoon':'Good evening';$('greeting').textContent=`${greeting}, ${displayName()}`}
function applyRoleUI(){document.querySelectorAll('.admin-only').forEach(el=>el.classList.toggle('hidden',!isAdmin()));$('profileRole').value=isAdmin()?'Admin':'Staff';document.querySelector('.bottom-nav')?.classList.toggle('has-personal',isAdmin());if(!isAdmin()&&state.currentView==='personalView')openView('dashboardView',false);}
function applyBranding(){const configured=state.settings.businessName||'Day One Projects',name=configured==='Tool Tracker'?'Day One Projects':configured;$('topbarSubtitle').innerHTML=`<em>Purpose Built.</em><span class="topbar-company"> · ${esc(name)}</span>`;const top=$('topLogoWrap');if(top)top.innerHTML='<img src="tt-logo.png" alt="Tool Tracker logo" />';const dash=$('dashboardLogo');if(dash){const src=state.settings.companyLogoURL||'day-one-projects-v44.png';dash.innerHTML=`<img src="${esc(src)}" alt="${esc(name)} logo" />`}}

async function ensureUserProfile(user){
  const refDoc=doc(db,'users',user.uid);const snap=await getDoc(refDoc);let data=snap.exists()?snap.data():null;
  if(!data){const all=await getDocs(collection(db,'users'));const role=all.size===0?'admin':'staff';data={email:user.email||'',displayName:user.displayName||user.email?.split('@')[0]||'Employee',role,active:true,createdAt:serverTimestamp(),updatedAt:serverTimestamp()};await setDoc(refDoc,data)}
  else if(!data.role){const all=await getDocs(collection(db,'users'));const role=all.size<=1?'admin':'staff';await setDoc(refDoc,{role,active:data.active!==false,updatedAt:serverTimestamp()},{merge:true});data={...data,role}}
  state.profile={id:user.uid,...data};
  if(!sessionStorage.getItem('tt-signin-recorded')){sessionStorage.setItem('tt-signin-recorded','1');addDoc(collection(db,'signins'),{uid:user.uid,email:user.email||'',displayName:data.displayName||displayName(user),createdAt:serverTimestamp()}).catch(()=>{})}
}
async function seedSettings(){const r=doc(db,'settings','app');const s=await getDoc(r);if(!s.exists())await setDoc(r,{businessName:'Day One Projects',logoURL:'',brandPrefixes:DEFAULT_PREFIXES,updatedAt:serverTimestamp(),updatedBy:state.user.uid})}
async function seedCategoriesIfEmpty(){if(!state.categories.length){for(let i=0;i<DEFAULT_CATEGORIES.length;i++){const [name,iconKey]=DEFAULT_CATEGORIES[i];await addDoc(collection(db,'categories'),{name,iconKey,active:true,order:i+1,createdAt:serverTimestamp(),updatedAt:serverTimestamp(),updatedBy:state.user.uid})}return}if(isAdmin()&&!state.categories.some(c=>String(c.name||'').toLowerCase()==='cordless batteries & chargers')){const max=Math.max(0,...state.categories.map(c=>Number(c.order)||0));await addDoc(collection(db,'categories'),{name:'Cordless Batteries & Chargers',iconKey:'cordless',active:true,order:max+1,createdAt:serverTimestamp(),updatedAt:serverTimestamp(),updatedBy:state.user.uid})}}
async function seedLocationsIfEmpty(){if(state.locations.length)return;for(const x of [{name:'Shop',type:'Shop'},{name:'In Transit',type:'Other'},{name:'Repair',type:'Repair'},{name:'Unassigned',type:'Other'}])await addDoc(collection(db,'locations'),{...x,active:true,createdAt:serverTimestamp(),updatedAt:serverTimestamp(),updatedBy:state.user.uid})}

async function migrateV435PoolLabels(){
  if(!isAdmin()||state.migratedV435)return;state.migratedV435=true;
  const occupied=new Set(state.tools.map(t=>String(t.label||'').toLowerCase()));
  const tool=state.tools.find(t=>(t.privateTool||t.inventoryScope==='personal')&&String(t.label||'').toUpperCase()==='P-B-43'&&String(t.brand||'').toLowerCase()==='bosch'&&String(t.model||'').toUpperCase()==='GKS18V-25C'&&(t.previousLabels||[]).some(x=>String(x).toUpperCase()==='P-B-03'));
  if(!tool||occupied.has('p-b-03'))return;
  await updateDoc(doc(db,'tools',tool.id),{label:'P-B-03',personalLabel:'P-B-03',companyLabel:tool.companyLabel||'B-26',previousLabels:[...(tool.previousLabels||[]),'P-B-43'],updatedAt:serverTimestamp(),updatedBy:state.user.uid,updatedByName:displayName()});
  await addDoc(collection(db,'personalHistory'),{toolId:tool.id,toolLabel:'P-B-03',toolName:tool.name||'Circular Saw',action:'Tool ID restored',note:'V4.3.5 pool-ID repair · P-B-43 → P-B-03',actorUid:state.user.uid,actorName:displayName(),privateTool:true,createdAt:serverTimestamp()});
}

function startRealtime(){
  state.unsubscribers.forEach(fn=>fn());state.unsubscribers=[];
  state.tools=[];state.toolsLoadState='loading';renderToolsLoadState();
  const sub=(source,handler,label)=>state.unsubscribers.push(onSnapshot(source,handler,e=>{if(label==='Tools'){state.tools=[];state.toolsLoadState='error';renderTools();renderCategories();updateStats();renderToolsLoadState()}toast(`${label}: ${e.message}`,true)}));
  sub(collection(db,'users'),snap=>{state.users=snap.docs.map(d=>({id:d.id,...d.data()}));const mine=state.users.find(u=>u.id===state.user.uid);if(mine){state.profile=mine;applyRoleUI();updateGreeting()}renderTeam()},'Team');
  sub(collection(db,'settings'),snap=>{const app=snap.docs.find(d=>d.id==='app');if(app)state.settings={businessName:'Day One Projects',logoURL:'',brandPrefixes:{...DEFAULT_PREFIXES},...app.data(),brandPrefixes:{...DEFAULT_PREFIXES,...(app.data().brandPrefixes||{})}};applyBranding();if($('businessName'))$('businessName').value=state.settings.businessName||'Day One Projects';renderPrefixes();updateLabelSuggestion()},'Settings');
  sub(collection(db,'locations'),snap=>{state.locations=snap.docs.map(d=>({id:d.id,...d.data()}));fillLocationSelects();renderLocations();renderTools();renderJobs();renderMap();seedLocationsIfEmpty().catch(console.error)},'Locations');
  sub(collection(db,'categories'),snap=>{state.categories=snap.docs.map(d=>({id:d.id,...d.data()}));fillCategorySelects();renderCategories();renderTools();seedCategoriesIfEmpty().catch(console.error)},'Categories');
  sub(collection(db,'jobs'),snap=>{state.jobs=snap.docs.map(d=>({id:d.id,...d.data()}));fillJobSelects();renderJobs();renderMap();fillCloseoutJobs();updateStats();if($('closeoutBody')?.dataset.jobId&&!$('closeoutModal')?.classList.contains('hidden'))loadCloseout();reconcileJobLocations().catch(console.error)},'Jobs');
  const toolSource=isAdmin()?query(collection(db,'tools'),orderBy('label')):query(collection(db,'tools'),where('privateTool','==',false),where('inventoryScope','==','company'));sub(toolSource,snap=>{state.toolsLoadState='loaded';state.tools=snap.docs.map(d=>({id:d.id,...d.data()}));if(isAdmin()&&!state.migratedLegacy){state.migratedLegacy=true;state.tools.filter(t=>{const personal=t.privateTool===true||t.inventoryScope==='personal';return t.privateTool!==personal||t.inventoryScope!==(personal?'personal':'company')}).forEach(t=>{const personal=t.privateTool===true||t.inventoryScope==='personal';updateDoc(doc(db,'tools',t.id),{privateTool:personal,inventoryScope:personal?'personal':'company'}).catch(e=>toast(`Ownership normalization failed: ${e.message}`,true))})}migrateV435PoolLabels().catch(console.error);renderTools();renderPersonalTools();renderNumberingReview();renderLocations();renderCategories();renderJobs();renderMap();renderWarranty();updateStats();updateLabelSuggestion();fillQuickMoveTools();v4Refresh();renderToolsLoadState();if($('closeoutBody')?.dataset.jobId&&!$('closeoutModal')?.classList.contains('hidden'))loadCloseout()},'Tools');
  sub(query(collection(db,'history'),orderBy('createdAt','desc'),limit(150)),snap=>{state.companyHistory=snap.docs.map(d=>({id:d.id,...d.data()}));mergeHistory()},'History');if(isAdmin())sub(query(collection(db,'personalHistory'),orderBy('createdAt','desc'),limit(150)),snap=>{state.personalHistory=snap.docs.map(d=>({id:d.id,...d.data()}));mergeHistory()},'Personal history');
  sub(collection(db,'wishlist'),snap=>{state.wishlist=snap.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>((b.createdAt?.seconds||0)-(a.createdAt?.seconds||0)));renderWishlist();updateStats()},'Wishlist');
  if(isAdmin())sub(collection(db,'verificationPhotos'),snap=>{state.verificationPhotos=snap.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>((b.createdAt?.seconds||0)-(a.createdAt?.seconds||0)));renderMasterPhotos();if(!$('photoHistoryModal')?.classList.contains('hidden')){const title=$('photoHistoryTitle')?.textContent||'';const t=state.tools.find(x=>title.startsWith(x.label||'__no__'));if(t)showPhotoHistory(t.id)}},'Verification photos');
  seedSettings().catch(console.error);
}

function openView(id,push=true){
  if(['adminView','personalView','photosView','insuranceView','renumberView'].includes(id)&&!isAdmin())return toast('Admin access only.',true);
  if(!$(id))return;
  document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===id));
  document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.openView===id||(id==='dashboardView'&&b.dataset.openView==='dashboardView')));
  if(id==='moraleView'&&state.currentView!==id){moraleJokeOffset=0;renderDepartmentJoke()}
  state.currentView=id;
  if(id==='personalView')renderPersonalTools();
  if(id==='mapView')setTimeout(renderMap,80);if(id==='photosView')renderMasterPhotos();if(id==='insuranceView')renderInsurance();if(id==='renumberView')renderRenumber();if(id==='reportsView')renderReports();if(id==='moraleView')renderMorale();if(id==='attentionView')renderAttentionQueue();if(id==='missingView')renderMissingQueue();if(id==='assignmentsView')renderAssignments();if(id==='estimateGameView')renderEstimateGame();
  if(push&&!state.suppressHistory){const cur=history.state?.view;if(cur!==id)history.pushState({view:id},'',location.href)}
  window.scrollTo({top:0,behavior:'smooth'});
}
function activeCompanyTools(){return companyTools().filter(t=>t.status!=='Retired')}
function renderToolsLoadState(){
  const status=state.toolsLoadState,loaded=status==='loaded';
  const message=status==='error'?'Company inventory could not load. Check access permissions and try signing in again.':'Loading company inventory…';
  const banner=$('inventoryLoadStatus');if(banner){banner.classList.toggle('hidden',loaded);banner.textContent=message;banner.setAttribute('role',status==='error'?'alert':'status')}
  if(!loaded){for(const id of ['statTotal','statAttention','statMissing'])if($(id))$(id).textContent='—';if($('moraleJoke'))$('moraleJoke').textContent=status==='error'?'Inventory unavailable. The Morale Department has no comment.':'The crew is reporting in. Inventory is loading.'}
}
function updateStats(){const tools=activeCompanyTools();$('statTotal').textContent=tools.length;$('statJobs').textContent=state.jobs.filter(j=>j.status==='Active').length;$('statAttention').textContent=tools.filter(t=>verificationState(t).needs||t.needsAttention||t.condition==='Damaged'||t.condition==='Needs Service'||t.status==='Repair').length;if($('statMissing'))$('statMissing').textContent=tools.filter(t=>['Missing','Lost'].includes(t.status)).length;renderToolsLoadState()}
function mergeHistory(){state.history=[...state.companyHistory,...(isAdmin()?state.personalHistory:[])].sort((a,b)=>(b.createdAt?.seconds||0)-(a.createdAt?.seconds||0));renderHistory();renderDashboardActivity()}
function renderDashboardActivity(){const max=matchMedia('(max-width: 700px)').matches?3:5;const rows=state.history.filter(h=>!h.privateTool).slice(0,max);$('dashboardActivity').innerHTML=rows.length?rows.map(historyHTML).join(''):'<div class="empty">Your first tool changes will appear here.</div>'}
function initials(name){return formatPersonName(name||'Employee').split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase()}
function historyHTML(h){const u=state.users.find(x=>x.id===h.actorUid),avatar=u?.avatarURL;return`<div class="history-item"><span class="history-avatar">${avatar?`<img src="${esc(avatar)}" alt="">`:esc(initials(h.actorName))}</span><strong>${esc(h.toolLabel||'')} ${esc(h.toolName||'')}</strong><div>${esc(h.action||'Updated')}${h.note?` — ${esc(h.note)}`:''}</div><time>${esc(formatPersonName(h.actorName||'Employee'))} · ${formatDate(h.createdAt)}</time></div>`}
function historyType(h){const a=String(h.action||'').toLowerCase(),n=String(h.note||'').toLowerCase();if(a.includes('ownership transfer')||a.includes('transferred to'))return'transfers';if(a.includes('verified'))return'verification';if(a.includes('tool id'))return'ids';if(a.includes('added'))return'added';if(a.includes('condition')||a.includes('status')||a.includes('attention')||a.includes('repair')||a.includes('damag'))return'condition';if(a.includes('moved')||a.includes('location')||a.includes('→')||n.includes('→'))return'moves';return'other'}
function historyDate(h){return h.createdAt?.toDate?h.createdAt.toDate():new Date(h.createdAt||0)}
function historyGroupLabel(d){const now=new Date(),startToday=new Date(now.getFullYear(),now.getMonth(),now.getDate()),startYesterday=new Date(startToday);startYesterday.setDate(startYesterday.getDate()-1);const startWeek=new Date(startToday);startWeek.setDate(startWeek.getDate()-6);if(d>=startToday)return'Today';if(d>=startYesterday)return'Yesterday';if(d>=startWeek)return'This Week';return d.toLocaleDateString([],{month:'long',year:'numeric'})}
function renderHistory(){if(!$('historyList'))return;const q=($('historySearch')?.value||'').trim().toLowerCase(),filter=state.historyFilter||'all',date=$('historyDate')?.value||'';let rows=(isAdmin()?state.history:state.companyHistory).filter(h=>{const type=historyType(h);if(filter!=='all'&&type!==filter)return false;if(date){const d=historyDate(h),local=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;if(local!==date)return false}if(!q)return true;return[h.toolLabel,h.toolName,h.action,h.note,h.actorName].some(v=>String(v||'').toLowerCase().includes(q))});if(!rows.length){$('historyList').innerHTML='<div class="panel empty">No matching tool history.</div>';return}const groups=[];for(const h of rows){const label=historyGroupLabel(historyDate(h));let g=groups.find(x=>x.label===label);if(!g){g={label,rows:[]};groups.push(g)}g.rows.push(h)}$('historyList').innerHTML=groups.map(g=>`<section class="history-group"><div class="history-group-title">${esc(g.label)}</div><div class="panel"><div class="panel-body timeline">${g.rows.map(historyHTML).join('')}</div></div></section>`).join('')}

function fillLocationSelects(){const active=activeLocations(),jobsites=active.filter(x=>x.type==='Jobsite'),other=active.filter(x=>x.type!=='Jobsite');const jobOpts=jobsites.map(x=>`<option value="${esc(x.id)}">${esc(x.name)} — Jobsite</option>`).join(''),otherOpts=other.map(x=>`<option value="${esc(x.id)}">${esc(x.name)} — ${esc(x.type||'Other')}</option>`).join('');const opts=(jobOpts?`<optgroup label="Jobsites">${jobOpts}</optgroup>`:'')+(otherOpts?`<optgroup label="Other locations">${otherOpts}</optgroup>`:'');$('toolLocation').innerHTML=opts;$('moveLocation').innerHTML=opts;if($('verifyLocation'))$('verifyLocation').innerHTML=opts;$('locationFilter').innerHTML='<option value="">All locations</option>'+active.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}${x.type==='Jobsite'?' — Jobsite':''}</option>`).join('')}
function fillCategorySelects(){const cats=activeCategories();$('toolCategory').innerHTML='<option value="">Uncategorized</option>'+cats.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');$('categoryFilter').innerHTML='<option value="">All categories</option>'+cats.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}
function fillJobSelects(){$('locationJob').innerHTML='<option value="">None</option>'+state.jobs.filter(j=>j.status!=='Completed').sort((a,b)=>(a.name||'').localeCompare(b.name||'')).map(j=>`<option value="${esc(j.id)}">${esc(j.name)}</option>`).join('')}
function filteredTools(){const q=$('searchInput').value.trim().toLowerCase(),status=$('statusFilter').value,loc=$('locationFilter').value,cat=$('categoryFilter').value,power=$('powerFilter')?.value||'';let rows=companyTools().filter(t=>{const hay=[t.label,t.name,t.brand,t.model,t.serial,t.identifyingMark,t.categoryName,t.category,t.locationName,t.powerType].join(' ').toLowerCase();const catMatch=!cat||t.categoryId===cat||(!t.categoryId&&currentCategory(cat)?.name===t.category);const powerMatch=!power||(power==='Not set'?!t.powerType:t.powerType===power);const statusMatch=status?t.status===status:t.status!=='Retired';return(!q||hay.includes(q))&&statusMatch&&(!loc||t.locationId===loc)&&catMatch&&powerMatch});if(state.toolJobFilter){const ids=new Set(state.locations.filter(l=>l.jobId===state.toolJobFilter).map(l=>l.id));rows=rows.filter(t=>ids.has(t.locationId))}if(state.specialToolFilter==='attention')rows=rows.filter(t=>verificationState(t).needs);if(state.specialToolFilter==='missing')rows=rows.filter(t=>['Missing','Lost'].includes(t.status));if(state.specialToolFilter==='uncategorized')rows=rows.filter(t=>!t.categoryId&&!t.categoryName&&!t.category);if(state.specialToolFilter==='matching')rows=rows.filter(t=>(state.matchingToolIds||[]).includes(t.id));if(String(state.specialToolFilter||'').startsWith('legacy:')){const name=state.specialToolFilter.slice(7);rows=rows.filter(t=>!t.categoryId&&(t.categoryName||t.category)===name)}return rows}
function toolImage(t){return t.photoURL||''}
function renderTools(){if(!$('toolsGrid'))return;const rows=filteredTools(),q=$('searchInput').value.trim(),cat=$('categoryFilter').value;const browseCategories=!q&&!cat&&!state.specialToolFilter;if(!rows.length){$('toolsGrid').innerHTML='<div class="panel empty" style="grid-column:1/-1">No tools match this view.</div>';return}if(browseCategories){const groups=new Map();for(const t of rows){const uncategorized=!t.categoryId&&!t.categoryName&&!t.category,id=uncategorized?'uncategorized':(t.categoryId||`legacy:${t.categoryName||t.category}`),name=uncategorized?'Uncategorized':(t.categoryName||t.category);if(!groups.has(id))groups.set(id,{id,name,tools:[]});groups.get(id).tools.push(t)}const order=new Map(state.categories.map((x,i)=>[x.id,x.order??i]));const cats=[...groups.values()].sort((x,y)=>(order.get(x.id)??999)-(order.get(y.id)??999)||x.name.localeCompare(y.name));$('toolsGrid').innerHTML=cats.map(g=>{const cover=g.tools.map(toolImage).find(Boolean),legacy=g.id==='uncategorized'||g.id.startsWith('legacy:'),target=legacy&&g.tools.length===1?`data-view-tool="${esc(g.tools[0].id)}"`:`data-browse-category="${esc(g.id)}"`;return`<button class="inventory-category-card" type="button" ${target}>${cover?`<img src="${esc(cover)}" alt="${esc(g.name)}" loading="lazy">`:`<div class="category-cover-placeholder">${icon('categories')}</div>`}<span class="category-cover-copy"><strong>${esc(g.name)}</strong><small>${g.tools.length} asset${g.tools.length===1?'':'s'}</small></span><b>›</b></button>`}).join('');return}$('toolsGrid').innerHTML=rows.map(t=>{const img=toolImage(t),catName=t.categoryName||t.category||'Uncategorized',verify=verificationState(t);return`<article class="tool-card" data-view-tool="${t.id}" tabindex="0" aria-label="Open ${esc(t.name||'tool')} details">${img?`<img class="tool-thumb" src="${esc(img)}" alt="${esc(t.name)}" loading="lazy" />`:`<div class="tool-placeholder">${icon('tools')}</div>`}<div class="tool-content"><div class="tool-title"><h3>${esc(t.name||'Unnamed tool')}</h3><span class="label">${esc(t.label||'—')}</span></div><div class="card-actions"><span class="badge ${slugStatus(t.status)}">${esc(t.status||'Available')}</span>${t.privateTool?'<span class="badge">Private</span>':''}${t.needsAttention?`<span class="badge repair">Needs Attention</span>`:''}${verify.needs?`<button class="badge verify-due verify-action" type="button" data-verify-tool="${t.id}">${esc(verify.label)}</button>`:'<span class="badge verified">Verified</span>'}</div><div class="meta"><span>📍 ${esc(t.locationName||'Unassigned')}</span><span>${esc(catName)}${t.brand?` · ${esc(t.brand)}`:''}${t.model?` · ${esc(t.model)}`:''}</span>${t.identifyingMark?`<span>Mark: ${esc(t.identifyingMark)}</span>`:''}<span>Last verified: ${t.lastVerified?formatDateOnly(t.lastVerified):'Not yet'}</span></div><div class="card-actions"><button class="btn accent smallbtn" data-move-tool="${t.id}">Quick Move</button><button class="btn smallbtn" data-edit-tool="${t.id}">Edit</button><button class="btn smallbtn" data-view-tool="${t.id}">Details</button></div></div></article>`}).join('')}
function renderLocations(){const rows=[...state.locations].sort((a,b)=>(a.name||'').localeCompare(b.name||''));$('locationsList').innerHTML=rows.length?rows.map(l=>{const count=visibleTools().filter(t=>t.locationId===l.id).length;const job=currentJob(l.jobId);return`<div class="info-card clickable-card" role="button" tabindex="0" data-view-location="${l.id}"><div class="info-card-head"><div><h3>${esc(l.name)}</h3><p>${esc(l.type||'Other')}${job?` · ${esc(job.name)}`:''}</p></div>${isAdmin()?`<button class="btn smallbtn" data-edit-location="${l.id}">Edit</button>`:''}</div><div class="info-meta"><span>${count} tool${count===1?'':'s'}</span><span>${l.active===false?'Inactive':'Active'}</span><span class="open-filter-hint">View inventory ›</span></div></div>`}).join(''):'<div class="panel empty">No locations yet.</div>'}
function renderJobs(){const rows=[...state.jobs].sort((a,b)=>((a.status==='Active'?0:1)-(b.status==='Active'?0:1))||(a.name||'').localeCompare(b.name||''));$('jobsList').innerHTML=rows.length?rows.map(j=>{const ids=new Set(state.locations.filter(l=>l.jobId===j.id).map(l=>l.id));const count=visibleTools().filter(t=>ids.has(t.locationId)).length;return`<div class="info-card"><div class="info-card-head"><div><h3>${esc(j.name)}</h3><p>${esc(j.address||'No address entered')}</p></div><span class="badge ${j.status==='Active'?'available':''}">${esc(j.status||'Active')}</span></div><div class="info-meta"><span>${count} tool${count===1?'':'s'} onsite</span>${j.contact?`<span>Contact: ${esc(j.contact)}</span>`:''}</div><div class="card-actions">${j.address?`<a class="btn smallbtn" href="${mapsURL(j.address)}" target="_blank" rel="noopener">Open Maps</a>`:''}<button class="btn accent smallbtn" data-job-tools="${j.id}">View tools</button>${isAdmin()?`<button class="btn smallbtn" data-edit-job="${j.id}">Edit</button>`:''}</div></div>`}).join(''):'<div class="panel empty">No jobsites yet. Add your first job and it will automatically become a tool location.</div>'}

async function geocodeAddress(address){
  if(!address)return null;const key='tt-geo-'+address.toLowerCase();try{const cached=JSON.parse(localStorage.getItem(key)||'null');if(cached?.lat&&cached?.lon)return cached}catch{}
  try{const r=await fetch(`https://nominatim.openstreetmap.org/search?format=json&limit=1&countrycodes=ca&q=${encodeURIComponent(address)}`,{headers:{'Accept':'application/json'}});if(!r.ok)throw new Error('geocode');const data=await r.json();if(!data[0])return null;const point={lat:Number(data[0].lat),lon:Number(data[0].lon)};localStorage.setItem(key,JSON.stringify(point));return point}catch(err){console.warn('Map geocoding failed',address,err);return null}
}
async function renderMap(){
  const el=$('liveMap');if(!el||state.currentView!=='mapView'||!window.L)return;const jobs=state.jobs.filter(j=>j.status==='Active'&&j.address);
  if(!state.leafletMap){state.leafletMap=L.map(el,{zoomControl:true}).setView([49.15,-122.9],9);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(state.leafletMap)}
  setTimeout(()=>state.leafletMap.invalidateSize(),50);state.mapMarkers.forEach(m=>m.remove());state.mapMarkers=[];
  if(!jobs.length){$('mapStatus').textContent='No active jobs with addresses yet.';return}$('mapStatus').textContent='Locating active jobs…';const bounds=[];let found=0;
  for(const j of jobs){const point=await geocodeAddress(j.address);if(!point)continue;const ids=new Set(state.locations.filter(l=>l.jobId===j.id).map(l=>l.id)),tools=companyTools().filter(t=>ids.has(t.locationId)),attention=tools.filter(t=>verificationState(t).needs).length;const popup=`<div class="map-popup"><h3>${esc(j.name)}</h3><p>${esc(j.address)}</p><strong>${tools.length} tool${tools.length===1?'':'s'} · ${attention?`${attention} need attention`:'all current'}</strong><br><a class="btn smallbtn" href="${mapsURL(j.address)}" target="_blank" rel="noopener">Directions</a> <button class="btn accent smallbtn" data-map-job="${j.id}">View inventory</button></div>`;const marker=L.marker([point.lat,point.lon]).addTo(state.leafletMap).bindPopup(popup);state.mapMarkers.push(marker);bounds.push([point.lat,point.lon]);found++}
  if(bounds.length===1)state.leafletMap.setView(bounds[0],13);else if(bounds.length>1)state.leafletMap.fitBounds(bounds,{padding:[35,35]});$('mapStatus').textContent=found===jobs.length?`${found} active jobsite pin${found===1?'':'s'} shown.`:`${found} of ${jobs.length} active job addresses could be located. Check any missing address.`
}

function categoryIconKey(c){const current=c.iconKey||'other',n=String(c.name||'').toLowerCase();const rules=[['pneumatic nail','pneumaticNailer'],['air line','airhose'],['air hose','airhose'],['electrical cord','cord'],['extension cord','cord'],['saw stand','stand'],['stand','stand'],['ladder','ladder'],['scaffold','scaffold'],['harness','safety'],['lifeline','safety'],['safety','safety'],['tool storage','storage'],['jobox','storage'],['compressor','compressor'],['nailer','nailer'],['nail gun','nailer'],['grinder','grinder'],['generator','generator'],['light','lighting'],['vacuum','vacuum'],['laser','laser'],['rotary','concrete'],['concrete','concrete'],['drill','drill'],['saw','saw']];const mapped=rules.find(([word])=>n.includes(word))?.[1];return mapped||current||'other'}
function renderCategories(){const rows=[...state.categories].filter(c=>!['cordless','corded','cordless tools','corded tools'].includes(String(c.name||'').toLowerCase())).sort((a,b)=>(a.order??999)-(b.order??999));const masters=rows.map((c,i)=>{const count=visibleTools().filter(t=>t.status!=='Retired'&&(t.categoryId===c.id||(!t.categoryId&&t.category===c.name))).length;return`<div class="info-card clickable-card" role="button" tabindex="0" data-view-category="${c.id}"><div class="info-card-head"><div class="brand"><span class="tile-icon" style="width:42px;height:42px">${icon(categoryIconKey(c))}</span><div><h3>${esc(c.name)}</h3><p>${count} tool${count===1?'':'s'} · ${c.active===false?'Inactive':'Active'}</p></div></div>${isAdmin()?`<div class="card-actions"><button class="btn smallbtn" data-category-up="${c.id}" ${i===0?'disabled':''}>↑</button><button class="btn smallbtn" data-category-down="${c.id}" ${i===rows.length-1?'disabled':''}>↓</button><button class="btn smallbtn" data-edit-category="${c.id}">Edit</button></div>`:''}</div><div class="info-meta"><span class="open-filter-hint">View inventory ›</span></div></div>`}).join('');$('categoriesList').innerHTML=masters||'<div class="panel empty">No categories yet.</div>'}
function activeWishlistRows(){return state.wishlist.filter(w=>!['Purchased','Declined'].includes(w.status||'Requested'))}
