function renderWishlist(){const rows=state.wishlist,active=crewActiveWishlistCount(),remaining=Math.max(0,3-active);if($('wishlistAllowance'))$('wishlistAllowance').innerHTML=isAdmin()?'<div class="panel compact-panel"><div class="panel-body small muted"><strong>Wishlist allowance</strong><br><strong>3 active requests per crew member</strong><br><span class="small muted">Resolving a request opens a slot.</span></div></div>':`<div class="panel compact-panel"><div class="panel-body"><strong>${remaining} request slot${remaining===1?'':'s'} available</strong><span class="small muted">You can have up to 3 active requests. A slot reopens when one is purchased or declined.</span></div></div>`;if($('addWishBtn')){$('addWishBtn').disabled=!isAdmin()&&active>=3;$('addWishBtn').title=!isAdmin()&&active>=3?'You already have 3 active requests.':''} $('wishlistList').innerHTML=rows.length?rows.map(w=>{const canEdit=isAdmin()||(w.requestedBy===state.user.uid&&!['Purchased','Declined'].includes(w.status||'Requested'));return`<div class="info-card"><div class="info-card-head"><div><h3>${esc(w.name)}</h3><p>${esc(w.brand||'')}${w.reason?`${w.brand?' · ':''}${esc(w.reason)}`:''}</p></div><span class="badge ${slugStatus(w.status)}">${esc(w.status||'Requested')}</span></div><div class="info-meta"><span>${esc(w.priority||'Nice to have')}</span><span>Suggested by ${esc(formatPersonName(w.requestedByName||'Crew'))}</span><span>${formatDate(w.createdAt)}</span></div>${canEdit?`<div class="card-actions"><button class="btn smallbtn" data-edit-wish="${w.id}">Edit</button></div>`:''}</div>`}).join(''):'<div class="panel empty">No wishlist items yet. Crew suggestions will show here.</div>'}
