  const completeFields=all.reduce((n,t)=>n+[serialReady(t),!!t.photoURL,Number(t.replacementCost)>0].filter(Boolean).length,0),pct=all.length?Math.round(completeFields/(all.length*3)*100):100;
  $('insuredCount').textContent=all.length;$('replacementTotal').textContent=total.toLocaleString('en-CA',{style:'currency',currency:'CAD',maximumFractionDigits:0});$('missingSerialCount').textContent=missingSerial;$('missingEvidenceCount').textContent=missingPhoto;$('insuranceCompleteness').textContent=`${pct}% complete`;renderInsuranceSummary();
