async function saveInsuranceReadiness(id){
  if(!isAdmin())return;const t=state.tools.find(x=>x.id===id),row=document.querySelector(`[data-insurance-row="${CSS.escape(id)}"]`);if(!t||!row)return;
  const na=!!row.querySelector('[data-insurance-na]')?.checked,serial=na?'':(row.querySelector('[data-insurance-serial]')?.value||'').trim(),replacementRaw=row.querySelector('[data-insurance-value]')?.value||'',photo=row.querySelector('[data-insurance-photo]')?.files?.[0],btn=row.querySelector('[data-save-insurance]');
  if(replacementRaw&&(!Number.isFinite(Number(replacementRaw))||Number(replacementRaw)<0))return toast('Enter a valid replacement value.',true);
  const duplicate=serial&&state.tools.find(x=>x.id!==id&&x.status!=='Retired'&&String(x.serial||'').trim().toLowerCase()===serial.toLowerCase());if(duplicate&&!confirm(`Serial ${serial} already belongs to ${duplicate.label||'another asset'}. Save anyway?`))return;
  if(btn){btn.disabled=true;btn.classList.add('busy');btn.textContent=photo?'Uploading…':'Saving…'}
  try{const payload={serial,serialNotApplicable:na,replacementCost:replacementRaw?Number(replacementRaw):'',replacementCostReviewedAt:replacementRaw?new Date().toISOString().slice(0,10):'',replacementCostBasis:replacementRaw?'manual/admin':'',updatedAt:serverTimestamp(),updatedBy:state.user.uid,updatedByName:displayName()};let photoData=null;if(photo){photoData=await uploadFileForTool(id,photo,'tool',!!(t.privateTool||t.inventoryScope==='personal'));payload.photoURL=photoData.url;payload.photoPath=photoData.path;payload.conditionPhotoAt=new Date().toISOString().slice(0,10)}await updateDoc(doc(db,'tools',id),payload);if(photoData)await writeConditionPhotoRecord({...t,...payload},photoData,t.condition||'Good','Insurance readiness photo','insurance-photo');const changes=[na?'Serial marked N/A':`Serial recorded: ${serial}`,replacementRaw?`Replacement cost: $${Number(replacementRaw).toFixed(2)}`:'Replacement cost not set',photo?'Current photo updated':''].filter(Boolean).join(' · ');await writeHistory({...t,...payload},'Insurance information updated',changes);toast(`${t.label||'Asset'} insurance information saved.`)}catch(err){console.error(err);toast(err.message||'Insurance update failed.',true)}finally{if(btn){btn.disabled=false;btn.classList.remove('busy');btn.textContent='Save changes'}}
}
async function saveReplacement(id,value){if(!isAdmin())return;await updateDoc(doc(db,'tools',id),{replacementCost:Number(value)||'',replacementCostReviewedAt:new Date().toISOString().slice(0,10),replacementCostBasis:'manual/admin',updatedAt:serverTimestamp(),updatedBy:state.user.uid,updatedByName:displayName()});const t=state.tools.find(x=>x.id===id);await writeHistory(t,'Replacement cost reviewed',value?`Current replacement cost: $${Number(value).toFixed(2)}`:'Replacement value cleared');toast('Replacement value saved.')}
function captureRenumberPending(){document.querySelectorAll('[data-renumber-id]').forEach(i=>{const v=i.value.trim(),old=i.dataset.oldLabel.trim();if(v!==old)state.renumberPending.set(i.dataset.renumberId,{old,next:v});else state.renumberPending.delete(i.dataset.renumberId)})}
function renderRenumber(){if(!isAdmin()||!$('renumberList'))return;captureRenumberPending();const q=($('renumberSearch')?.value||'').toLowerCase();const rows=companyTools().filter(t=>t.status!=='Retired').filter(t=>!q||[t.label,t.name,t.brand,t.model,t.serial,t.identifyingMark,t.categoryName,t.status].join(' ').toLowerCase().includes(q));const shown=rows.slice(0,state.renumberLimit);$('renumberList').innerHTML=`<div class="dataset-count">Showing ${shown.length} of ${rows.length}</div>`+shown.map(t=>{const pending=state.renumberPending.get(t.id),img=toolImage(t);return`<div class="renumber-row admin-tool-row">${img?`<img src="${esc(img)}" alt="" loading="lazy">`:`<span class="admin-tool-placeholder">${icon('tools')}</span>`}<span><strong>${esc(t.label||'—')} · ${esc(t.name||'Tool')}</strong><small>${esc(t.brand||'')} ${esc(t.model||'')} · ${esc(t.categoryName||t.category||'Uncategorized')} · ${esc(t.status||'Available')}</small><small>${t.serial?`Serial: ${esc(t.serial)}`:'No serial'}${t.identifyingMark?` · Mark: ${esc(t.identifyingMark)}`:''}</small></span><input data-renumber-id="${t.id}" data-old-label="${esc(t.label||'')}" value="${esc(pending?.next??t.label??'')}" aria-label="New Tool ID"></div>`}).join('');const more=$('renumberLoadMore');if(more){more.classList.toggle('hidden',rows.length<=state.renumberLimit);more.textContent=`Load more (${Math.min(25,rows.length-state.renumberLimit)} more)`}}
async function applyRenumber(){if(!isAdmin())return;captureRenumberPending();const changes=[...state.renumberPending.entries()].map(([id,v])=>({id,old:v.old,next:v.next})).filter(x=>x.next&&x.next!==x.old);if(!changes.length)return toast('No Tool ID changes to apply.');const finals=new Map(companyTools().map(t=>[t.id,t.label]));changes.forEach(c=>finals.set(c.id,c.next));const labels=[...finals.values()].map(x=>String(x).toLowerCase());if(new Set(labels).size!==labels.length)return toast('Two tools would end up with the same Tool ID.',true);if(!confirm(`Apply ${changes.length} Tool ID change${changes.length===1?'':'s'}? History will preserve every old → new label.`))return;const batch=writeBatch(db);for(const c of changes)batch.update(doc(db,'tools',c.id),{label:c.next,previousLabels:[...(state.tools.find(t=>t.id===c.id)?.previousLabels||[]),c.old],updatedAt:serverTimestamp(),updatedBy:state.user.uid,updatedByName:displayName()});await batch.commit();for(const c of changes){const t=state.tools.find(x=>x.id===c.id);await writeHistory({...t,label:c.next},'Tool ID changed by Admin',`${c.old} → ${c.next}`)}state.renumberPending.clear();toast(`${changes.length} Tool ID${changes.length===1?'':'s'} updated.`)}
async function markAttention(id){const t=state.tools.find(x=>x.id===id);if(!t)return;const reason=prompt('What needs attention?');if(!reason)return;await updateDoc(doc(db,'tools',id),{needsAttention:true,attentionReason:reason,attentionReportedBy:state.user.uid,attentionReportedByName:displayName(),attentionReportedAt:new Date().toISOString(),attentionDeferredUntil:'',updatedAt:serverTimestamp(),updatedBy:state.user.uid,updatedByName:displayName()});await writeHistory(t,'Needs Attention reported',reason);toast('Admin has been flagged.')}
async function adminAttention(id,action){if(!isAdmin())return;const t=state.tools.find(x=>x.id===id);if(!t)return;if(action==='resolve'){const note=prompt('Resolution note (optional):')||'';await updateDoc(doc(db,'tools',id),{needsAttention:false,attentionReason:'',attentionDeferredUntil:'',updatedAt:serverTimestamp(),updatedBy:state.user.uid,updatedByName:displayName()});await writeHistory(t,'Needs Attention resolved',note);toast('Attention item resolved.')}else{const date=prompt('Defer until (YYYY-MM-DD):',new Date(Date.now()+90*86400000).toISOString().slice(0,10));if(!date)return;const note=prompt('Reason (optional):','Service during slower season')||'';await updateDoc(doc(db,'tools',id),{needsAttention:true,attentionDeferredUntil:date,attentionDeferredReason:note,updatedAt:serverTimestamp(),updatedBy:state.user.uid,updatedByName:displayName()});await writeHistory(t,'Needs Attention deferred',`${date}${note?' · '+note:''}`);toast(`Deferred until ${date}.`)}}
function exportInsuranceCSV(){if(!isAdmin())return;const rows=insuranceRows(),total=rows.reduce((n,t)=>n+(Number(t.replacementCost)>0?Number(t.replacementCost):0),0),missing=rows.filter(t=>!(Number(t.replacementCost)>0)).length;const cols=['Inventory','Tool ID','Tool','Brand','Model','Serial or N/A','Replacement value CAD','Value status','Photo available','Location'];const data=rows.map(t=>[(t.privateTool||t.inventoryScope==='personal')?'Personal':'Company',t.label,t.name,t.brand,t.model,t.serialNotApplicable?'N/A':t.serial||'NOT RECORDED',Number(t.replacementCost)>0?Number(t.replacementCost).toFixed(2):'',''+(Number(t.replacementCost)>0?'Recorded':'MISSING VALUE'),t.photoURL?'Yes':'No',t.locationName||'']);data.push(['SUMMARY','Recorded replacement total CAD','','','','',total.toFixed(2),'Missing values: '+missing,'','']);csvDownload('Insurance-'+($('insuranceScope')?.value||'company'),cols,data)}

function csvDownload(name,cols,rows){const csv=[cols,...rows].map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=`Tool-Tracker-${name}-${new Date().toISOString().slice(0,10)}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function reportDataset(kind){const tools=companyTools();if(kind==='inventory')return{title:'Tool Inventory',cols:['Tool ID','Tool','Brand','Model','Serial','Category','Condition','Status','Location'],rows:tools.map(t=>[t.label,t.name,t.brand,t.model,t.serialNotApplicable?'N/A':t.serial,t.categoryName||t.category,t.condition,t.status,t.locationName])};if(kind==='insurance')return{title:'Insurance',cols:['Tool ID','Tool','Serial','Purchase Price','Replacement Cost','Current Photo','Last Verified'],rows:tools.filter(t=>t.status!=='Retired'&&t.insuranceIncluded!==false).map(t=>[t.label,t.name,t.serialNotApplicable?'N/A':t.serial,t.purchasePrice,t.replacementCost,t.photoURL?'Yes':'No',t.lastVerified])};if(kind==='repair')return{title:'Repair & Damage',cols:['Tool ID','Tool','Condition','Status','Needs Attention','Reason','Location'],rows:tools.filter(t=>t.condition==='Damaged'||t.condition==='Needs Service'||t.condition==='Missing Parts'||t.status==='Repair'||t.needsAttention).map(t=>[t.label,t.name,t.condition,t.status,t.needsAttention?'Yes':'No',t.attentionReason,t.locationName])};if(kind==='location')return{title:'Location / Job Inventory',cols:['Location','Tool ID','Tool','Status','Condition'],rows:[...tools].sort((a,b)=>String(a.locationName||'').localeCompare(String(b.locationName||''))).map(t=>[t.locationName,t.label,t.name,t.status,t.condition])};if(kind==='verification')return{title:'Verification',cols:['Tool ID','Tool','Last Verified','Verification State','Condition','Status','Location'],rows:tools.map(t=>{const v=verificationState(t);return[t.label,t.name,t.lastVerified,v.needs?v.label:'Verified',t.condition,t.status,t.locationName]})};return{title:'Tool History',cols:['Date','Tool ID','Tool','Action','Note','User'],rows:(isAdmin()?state.history:state.companyHistory).map(h=>[formatDate(h.createdAt),h.toolLabel,h.toolName,h.action,h.note,h.actorName])}}
function renderReports(){if(!isAdmin()||!$('reportBody'))return;if(!state.activeReport){$('reportBody').innerHTML='<div class="empty">Choose a report above to preview it here.</div>';$('reportControls')?.classList.add('hidden');$('reportLoadMore')?.classList.add('hidden');return}const d=reportDataset(state.activeReport),q=($('reportSearch')?.value||'').toLowerCase();const rows=d.rows.filter(r=>!q||r.join(' ').toLowerCase().includes(q));$('reportTitle').textContent=d.title;$('exportReportBtn').classList.remove('hidden');$('reportControls')?.classList.remove('hidden');const shown=rows.slice(0,state.reportLimit);$('reportBody').innerHTML=`<div class="report-preview"><strong>Showing ${shown.length} of ${rows.length} record${rows.length===1?'':'s'}</strong><div class="report-table-wrap"><table class="report-table"><thead><tr>${d.cols.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${shown.map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="small muted">In-app preview is batched for readability. Export CSV includes the full report.</p></div>`;const more=$('reportLoadMore');if(more){more.classList.toggle('hidden',rows.length<=state.reportLimit);more.textContent=`Load more (${Math.min(25,rows.length-state.reportLimit)} more)`}}
function chooseReport(kind){if(!isAdmin())return;state.activeReport=kind;state.reportLimit=25;if($('reportSearch'))$('reportSearch').value='';document.querySelectorAll('[data-report]').forEach(b=>b.classList.toggle('active',b.dataset.report===kind));renderReports()}
function exportActiveReport(){if(!state.activeReport)return;const d=reportDataset(state.activeReport),q=($('reportSearch')?.value||'').toLowerCase(),rows=d.rows.filter(r=>!q||r.join(' ').toLowerCase().includes(q));csvDownload(d.title.replace(/[^a-z0-9]+/gi,'-'),d.cols,rows)}

function queueCard(t,kind){const verify=verificationState(t),missing=kind==='missing';return`<article class="panel queue-card"><div class="panel-body"><div class="queue-head"><div><span class="eyebrow">${esc(t.label||'UNLABELLED')}</span><h3>${esc(t.name||'Tool')}</h3></div><span class="badge ${slugStatus(t.status)}">${esc(missing?'Missing':verify.label)}</span></div><p class="muted">${esc(t.brand||'')} ${esc(t.model||'')}</p><dl class="queue-facts"><div><dt>Last known location</dt><dd>${esc(t.locationName||'Unassigned')}</dd></div><div><dt>${missing?'Reported':'Reason'}</dt><dd>${esc(missing?(t.missingReportedAt?formatDate(t.missingReportedAt):'Date not recorded'):(t.attentionReason||verify.label))}</dd></div></dl><div class="card-actions">${missing?`<button class="btn accent" data-found-tool="${t.id}">Mark Found</button>`:`<button class="btn accent" data-verify-tool="${t.id}">Verify</button>${isAdmin()?`<button class="btn" data-attention-action="resolve" data-tool-id="${t.id}">Resolve</button><button class="btn" data-attention-action="defer" data-tool-id="${t.id}">Defer</button>`:''}`}<button class="btn" data-view-tool="${t.id}">Details</button><button class="btn" data-edit-tool="${t.id}">Edit</button></div></div></article>`}
function renderAttentionQueue(){const el=$('attentionQueue');if(!el)return;const rows=companyTools().filter(t=>t.status!=='Retired'&&!['Missing','Lost'].includes(t.status)&&verificationState(t).needs);el.innerHTML=rows.length?rows.map(t=>queueCard(t,'attention')).join(''):'<div class="empty queue-empty"><strong>No tools need attention.</strong><span>Everything is verified, serviceable and behaving suspiciously well.</span></div>'}
function renderMissingQueue(){const el=$('missingQueue');if(!el)return;const rows=companyTools().filter(t=>['Missing','Lost'].includes(t.status));el.innerHTML=rows.length?rows.map(t=>queueCard(t,'missing')).join(''):'<div class="empty queue-empty"><strong>No tools are missing.</strong><span>Enjoy this administrative miracle while it lasts.</span></div>'}
function renderAssignments(tab='mine'){const el=$('assignmentsList');if(!el)return;const rows=tab==='handoffs'?companyTools().filter(t=>t.handoffStatus==='pending'&&(isAdmin()||t.handoffToUid===state.user.uid||t.assignedToUid===state.user.uid)):companyTools().filter(t=>isAdmin()?t.assignedToUid:t.assignedToUid===state.user.uid);el.innerHTML=rows.length?rows.map(t=>`<article class="panel queue-card"><div class="panel-body"><span class="eyebrow">${esc(t.label||'')}</span><h3>${esc(t.name||'Tool')}</h3><p class="muted">Assigned to ${esc(t.assignedToName||'Unassigned')} · ${esc(t.locationName||'No location')}</p><div class="card-actions"><button class="btn" data-view-tool="${t.id}">Details</button>${t.handoffStatus==='pending'?'<span class="badge">Handoff pending</span>':''}</div></div></article>`).join(''):'<div class="empty"><strong>Nothing in this queue.</strong></div>'}

const ESTIMATE_SET_ID='weekly-takeoffs-v2';
function currentEstimateLevels(){return TAKEOFF_SETS[contentWeekIndex()]}

function estimateGraphic(type){const inner=type==='wall'?'<path d="M35 120h250M45 120V45M275 120V45M70 120V45M100 120V45M130 120V45M160 120V45M190 120V45M220 120V45M250 120V45"/><path d="M45 35h230M45 30v10M275 30v10"/><text x="132" y="25">12 ft</text>':type==='deck'?'<rect x="48" y="35" width="224" height="100"/><path d="M62 35v100M76 35v100M90 35v100M104 35v100M118 35v100M132 35v100M146 35v100M160 35v100M174 35v100M188 35v100M202 35v100M216 35v100M230 35v100M244 35v100M258 35v100"/><text x="142" y="25">10 ft</text><text x="278" y="88">8 ft</text>':'<rect x="45" y="32" width="230" height="112"/><rect x="135" y="32" width="50" height="32"/><path d="M45 144h90M185 144h90"/><text x="130" y="158">12 × 10 ft</text><text x="140" y="52">window</text><text x="143" y="138">door</text>';
 return`<svg class="estimate-drawing" viewBox="0 0 320 170" role="img" aria-label="Dimensioned construction sketch"><g>${inner}</g><g class="seasonal-pumpkin"><ellipse cx="28" cy="140" rx="18" ry="14"/><ellipse cx="20" cy="140" rx="10" ry="13"/><ellipse cx="36" cy="140" rx="10" ry="13"/><path d="M28 126v-7"/></g><g class="seasonal-bat"><path d="M272 25c7-12 13-8 18-2 5-6 11-10 18 2-7-2-9 4-10 10-5-5-11-5-16 0-1-6-3-12-10-10Z"/></g></svg>`}
function estimateState(){const key=`tt-estimate-${ESTIMATE_SET_ID}-${pacificWeekKey()}`;let data={};try{data=JSON.parse(localStorage.getItem(key)||'{}')}catch{}return{key,data}}
function renderEstimateGame(){const el=$('estimateLevels');if(!el)return;const {data}=estimateState(),complete=Object.keys(data).length;$('estimateProgress').textContent=`${complete} of 3`;$('estimateCardProgress').textContent=`${complete} of 3 complete`;el.innerHTML=currentEstimateLevels().map((level,i)=>{const locked=i>0&&!data[i-1],result=data[i],choices=Object.entries(level.choices).map(([key,label])=>`<button class="estimate-choice ${result?(key===level.answer?'correct':key===result.choice?'wrong':''):''}" data-estimate-answer="${i}:${key}" ${result?'disabled':''}><b>${key}</b><span>${label}</span></button>`).join('');return`<article class="panel estimate-level ${locked?'locked':''}"><div class="panel-body"><div class="queue-head"><div><span class="eyebrow">${i+1} · ${level.rank.toUpperCase()} ESTIMATE</span><h3>${level.title}</h3></div>${result?`<span class="badge ${result.correct?'verified':'repair'}">${result.correct?'Correct':'Incorrect'}</span>`:locked?'<span class="badge">Locked</span>':'<span class="badge">One guess</span>'}</div>${level.graphic}<p class="estimate-note">Training estimate only. Use the stated dimensions and assumptions.</p><p>${level.question}</p><div class="estimate-choices">${choices}</div><div class="card-actions"><button class="btn" data-estimate-hint="${i}" ${result||locked?'disabled':''}>Hint</button></div><p id="estimateFeedback${i}" class="estimate-feedback">${result?`<strong>${result.correct?'That will actually work. Management is concerned.':'That takeoff has joined the change-order department.'}</strong><br>${level.breakdown}`:''}</p></div></article>`}).join('')}
function answerEstimate(raw){const [iRaw,choice]=raw.split(':'),i=Number(iRaw),level=currentEstimateLevels()[i],stateData=estimateState();if(!level||stateData.data[i]||(i>0&&!stateData.data[i-1]))return;stateData.data[i]={choice,correct:choice===level.answer};localStorage.setItem(stateData.key,JSON.stringify(stateData.data));renderEstimateGame()}

function v4Refresh(){renderMorale();renderMasterPhotos();renderInsurance();renderRenumber();renderReports();renderAttentionQueue();renderMissingQueue();renderAssignments();renderEstimateGame()}

