const MORALE_FACT_EXPANSIONS=[["The sliding hook compensates for its thickness on both inside and outside measurements.", "A bent hook can shift the starting point of every measurement.", "Reading the blade straight on reduces errors from viewing it at an angle.", "Starting at a known mark avoids a damaged hook, but subtract that starting measurement.", "Use the same tape for related layout measurements to keep results consistent."], ["A duty cycle of 50% means running for only half of the stated cycle period.", "Check the manufacturer\u2019s stated cycle period; the percentage alone does not give the allowed runtime.", "Air leaks make the compressor cycle more frequently even when no tool is operating.", "Restricted airflow around the motor and pump makes cooling less effective.", "A tool\u2019s air demand must fit the compressor\u2019s delivery at the required working pressure."], ["A 6-8-10 triangle uses the same proportions as a 3-4-5 triangle.", "Longer layout measurements reduce the effect of a small marking error.", "Measure between the same reference points when checking all three sides.", "Equal diagonals help check a rectangular layout when its opposite sides are equal.", "A square corner depends on the measured layout, not on whether the existing wall looks straight."], ["Pulling a chalk line sideways can shift the mark away from the intended layout.", "Keeping the line taut helps produce a crisp mark.", "Too much chalk can leave a wide, dusty line that is harder to follow precisely.", "Choose chalk suited to the surface; some colours leave persistent stains.", "A chalk line marks a straight path between points but does not establish level by itself."]];
V44_MORALE_PACKAGES.forEach((pack,index)=>{pack.extraFacts=MORALE_FACT_EXPANSIONS[index]||[]});
function currentFacts(){return currentMoralePackage().extraFacts||[]}
function currentFactsKey(){return `tt-morale-facts-v3-${pacificWeekKey()}-${currentMoralePackage().puzzle.title}`}
function currentFactCount(){const count=Number(localStorage.getItem(currentFactsKey())||0);return Number.isFinite(count)?Math.max(0,Math.min(currentFacts().length,Math.floor(count))):0}
function renderExtraFacts(){if(!$('moreFacts'))return;const facts=currentFacts(),count=currentFactCount();$('moreFacts').innerHTML=facts.slice(0,count).map(f=>`<p>${esc(f)}</p>`).join('');if($('moreFactsBtn')){$('moreFactsBtn').disabled=count>=facts.length;$('moreFactsBtn').textContent=count>=facts.length?'That’s enough knowledge for company time.':'Unfortunately, tell me more.'}}
function restoreMoraleProgress(){if(localStorage.getItem(moralePuzzleKey())==='solved'&&$('puzzleResult')){$('puzzleResult').textContent='Completed for this week ✓';setPuzzleLocked(true)}renderExtraFacts()}
function revealNextFact(){const count=currentFactCount();if(count>=currentFacts().length)return;localStorage.setItem(currentFactsKey(),String(count+1));renderExtraFacts()}
$('moreFactsBtn')?.addEventListener('click',revealNextFact);restoreMoraleProgress();
renderMorale();

paintIcons();
applySeasonalDecor();
onAuthStateChanged(auth,async user=>{document.getElementById('startupSplash')?.classList.add('hidden');
  state.user=user;
  if(user){$('authScreen').classList.add('hidden');$('app').classList.remove('hidden');$('profileEmail').value=user.email||'';try{await ensureUserProfile(user);if(state.profile?.active===false){toast('This crew account is inactive.',true);await signOut(auth);return}$('currentUserName').textContent=displayName();$('displayNameInput').value=displayName();$('businessName').value=state.settings.businessName||'Day One Projects';$('profileTheme').value=state.profile.theme||localStorage.getItem('tt-theme')||'system';applyTheme($('profileTheme').value);applyRoleUI();updateGreeting();startRealtime();history.replaceState({view:'dashboardView'},'',location.href);openView('dashboardView',false)}catch(err){console.error(err);toast(`Firebase setup error: ${err.message}`,true)}}
  else{state.unsubscribers.forEach(fn=>fn());state.unsubscribers=[];$('app').classList.add('hidden');$('authScreen').classList.remove('hidden')}
});

window.addEventListener('popstate',e=>{state.suppressHistory=true;document.querySelectorAll('.modal:not(.hidden)').forEach(m=>m.classList.add('hidden'));openView(e.state?.view||'dashboardView',false);state.suppressHistory=false});

document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.tool-card[data-view-tool]')){e.preventDefault();viewTool(e.target.dataset.viewTool)}});

function renderNumberingReview(){
 if(!isAdmin())return;
 let box=$('numberingReview');if(!box){box=document.createElement('div');box.id='numberingReview';box.className='panel';$('personalView').appendChild(box)}
 const tools=personalTools(),laser=tools.find(t=>String(t.label).toUpperCase()==='P-B-44'&&String(t.brand).toLowerCase()==='bosch'&&String(t.model).toUpperCase().startsWith('GLL330-80'));
 const occupied=state.tools.some(t=>String(t.label).toUpperCase()==='P-B-25');
 box.innerHTML=laser?`<div class="panel-body"><h3>Personal Bosch numbering review</h3><p>${esc(laser.name)} · ${esc(laser.model)}: P-B-44 → P-B-25</p><p>${occupied?'P-B-25 is occupied. No correction available.':'Confirm this is the laser that should follow P-B-24. Its photos, receipts and history stay with it.'}</p><button class="btn primary" id="correctPersonalLaser" ${occupied?'disabled':''}>Correct laser ID to P-B-25</button></div>`:'';
 $('correctPersonalLaser')?.addEventListener('click',()=>correctPersonalLaser(laser.id));
}
async function correctPersonalLaser(id){
 if(!isAdmin()||!confirm('Correct this laser from P-B-44 to P-B-25? The old label will remain in history.'))return;
 try{
 const all=await getDocs(collection(db,'tools'));if(all.docs.some(d=>d.id!==id&&String(d.data().label).toUpperCase()==='P-B-25'))throw new Error('P-B-25 is already occupied. Nothing changed.');
 await runTransaction(db,async tx=>{const r=doc(db,'tools',id),snap=await tx.get(r),t=snap.data();if(!t||t.label!=='P-B-44'||!(t.privateTool===true||t.inventoryScope==='personal'))throw new Error('Record changed. Reopen the review.');
 const history=doc(collection(db,'personalHistory'));
 tx.update(r,{label:'P-B-25',personalLabel:'P-B-25',previousLabels:[...new Set([...(t.previousLabels||[]),'P-B-44'])],numberingCorrectionLabels:[...new Set([...(t.numberingCorrectionLabels||[]),'P-B-44'])],updatedAt:serverTimestamp(),updatedBy:state.user.uid,updatedByName:displayName()});
 tx.set(history,{toolId:id,toolLabel:'P-B-25',toolName:t.name||'Laser',action:'Tool ID corrected',note:'P-B-44 → P-B-25; mistaken number excluded from future suggestions.',actorUid:state.user.uid,actorName:displayName(),privateTool:true,createdAt:serverTimestamp()});});toast('Laser corrected to P-B-25.');
 }catch(err){toast(err.message,true)}
}

let lastCalendarKey=seasonalDate()+':'+pacificWeekKey();
function refreshCalendar(){const key=seasonalDate()+':'+pacificWeekKey();applySeasonalDecor();if(key!==lastCalendarKey){lastCalendarKey=key;if($('puzzleAnswer'))$('puzzleAnswer').value='';if($('puzzleResult'))$('puzzleResult').textContent='';renderMorale();renderEstimateGame()}}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshCalendar()});window.addEventListener('focus',refreshCalendar);setInterval(refreshCalendar,60000);

function moneyCAD(n){return Number(n||0).toLocaleString('en-CA',{style:'currency',currency:'CAD'})}
function insuranceRows(){const scope=$('insuranceScope')?.value||'company';return (scope==='personal'?personalTools():scope==='combined'?[...companyTools(),...personalTools()]:companyTools()).filter(t=>t.status!=='Retired'&&t.insuranceIncluded!==false).sort((a,b)=>String(a.label).localeCompare(String(b.label),undefined,{numeric:true}))}
function renderInsuranceSummary(){const el=$('insuranceSummary');if(!el)return;const rows=insuranceRows(),total=rows.reduce((n,t)=>n+(Number(t.replacementCost)>0?Number(t.replacementCost):0),0),missing=rows.filter(t=>!(Number(t.replacementCost)>0)).length;el.innerHTML=`<strong>Recorded replacement total: ${moneyCAD(total)}</strong><p>${missing} asset${missing===1?'':'s'} still missing replacement values. ${missing?'This total is incomplete.':'All included assets have a replacement value.'}</p><p>Renewal tool limit reported: ${moneyCAD(25000)}. ${$('insuranceScope').value==='company'&&total>25000?`Recorded company values exceed that limit by ${moneyCAD(total-25000)}.`:'Compare the applicable inventory with your broker; Personal tools are not assumed covered.'}</p><small>Export includes every included asset in this inventory scope, regardless of search, filter or loaded page. Updating insurance information does not change tool verification.</small>`}
$('insuranceScope')?.addEventListener('change',()=>{state.insuranceLimit=25;renderInsurance()});

function printInsuranceReport(){if(!isAdmin())return;const rows=insuranceRows(),scope=$('insuranceScope').value,total=rows.reduce((n,t)=>n+(Number(t.replacementCost)>0?Number(t.replacementCost):0),0),missing=rows.filter(t=>!(Number(t.replacementCost)>0)).length;const win=window.open('','_blank');if(!win)return toast('Allow the report window, then try again.',true);win.opener=null;win.document.write(`<!doctype html><html><head><title>Tool Tracker Insurance Inventory</title><style>body{font:12px Arial,sans-serif;color:#17212b;margin:30px}h1{color:#148dbb}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:7px;border-bottom:1px solid #ccd2d8}thead{display:table-header-group}tr{break-inside:avoid}.note{padding:12px;background:#eef5f8}@media print{button{display:none}body{margin:0}}</style></head><body><h1>Day One Projects</h1><h2>Tool insurance inventory · ${esc(scope)}</h2><p>Prepared ${esc(new Intl.DateTimeFormat('en-CA',{timeZone:'America/Vancouver'}).format(new Date()))} · ${rows.length} assets</p><div class="note"><strong>Recorded replacement total: ${moneyCAD(total)}</strong><p>${missing} missing replacement values. ${missing?'Total is incomplete.':'All included assets have a value.'}</p><p>Reported renewal tool limit: ${moneyCAD(25000)}. Confirm applicable assets and coverage with the broker.</p></div><p><button onclick="window.print()">Print / Save as PDF</button></p><table><thead><tr><th>Inventory / ID</th><th>Tool</th><th>Brand / model</th><th>Serial</th><th>Replacement CAD</th></tr></thead><tbody>${rows.map(t=>`<tr><td>${esc((t.privateTool||t.inventoryScope==='personal')?'Personal':'Company')}<br>${esc(t.label)}</td><td>${esc(t.name)}</td><td>${esc(t.brand||'')} ${esc(t.model||'')}</td><td>${esc(t.serialNotApplicable?'N/A':t.serial||'Not recorded')}</td><td>${Number(t.replacementCost)>0?moneyCAD(t.replacementCost):'MISSING VALUE'}</td></tr>`).join('')}</tbody></table><p>Retired and explicitly excluded assets are omitted. Values are recorded estimates, not an appraisal or confirmation of coverage. Purchase prices and verification dates are not substituted for replacement values.</p></body></html>`);win.document.close()}
$('printInsuranceBtn')?.addEventListener('click',printInsuranceReport);

document.addEventListener('visibilitychange',()=>{const layer=$('seasonEffectsLayer');if(layer)layer.classList.toggle('season-paused',document.hidden)});
